typedef struct{uint32_t h[8];uint64_t bits;unsigned char b[64];size_t used;}Sh;
static A210Counters g;
static uint32_t ro(uint32_t x,unsigned n){return(x>>n)|(x<<(32-n));}
static void sb(Sh*s,const unsigned char*b){static const uint32_t k[64]={0x428a2f98U,0x71374491U,0xb5c0fbcfU,0xe9b5dba5U,0x3956c25bU,0x59f111f1U,0x923f82a4U,0xab1c5ed5U,0xd807aa98U,0x12835b01U,0x243185beU,0x550c7dc3U,0x72be5d74U,0x80deb1feU,0x9bdc06a7U,0xc19bf174U,0xe49b69c1U,0xefbe4786U,0x0fc19dc6U,0x240ca1ccU,0x2de92c6fU,0x4a7484aaU,0x5cb0a9dcU,0x76f988daU,0x983e5152U,0xa831c66dU,0xb00327c8U,0xbf597fc7U,0xc6e00bf3U,0xd5a79147U,0x06ca6351U,0x14292967U,0x27b70a85U,0x2e1b2138U,0x4d2c6dfcU,0x53380d13U,0x650a7354U,0x766a0abbU,0x81c2c92eU,0x92722c85U,0xa2bfe8a1U,0xa81a664bU,0xc24b8b70U,0xc76c51a3U,0xd192e819U,0xd6990624U,0xf40e3585U,0x106aa070U,0x19a4c116U,0x1e376c08U,0x2748774cU,0x34b0bcb5U,0x391c0cb3U,0x4ed8aa4aU,0x5b9cca4fU,0x682e6ff3U,0x748f82eeU,0x78a5636fU,0x84c87814U,0x8cc70208U,0x90befffaU,0xa4506cebU,0xbef9a3f7U,0xc67178f2U};uint32_t w[64];for(int i=0;i<16;i++)w[i]=((uint32_t)b[4*i]<<24)|((uint32_t)b[4*i+1]<<16)|((uint32_t)b[4*i+2]<<8)|b[4*i+3];for(int i=16;i<64;i++){uint32_t x=w[i-15],y=w[i-2];w[i]=w[i-16]+(ro(x,7)^ro(x,18)^(x>>3))+w[i-7]+(ro(y,17)^ro(y,19)^(y>>10));}uint32_t a=s->h[0],bb=s->h[1],c=s->h[2],d=s->h[3],e=s->h[4],f=s->h[5],gg=s->h[6],h=s->h[7];for(int i=0;i<64;i++){uint32_t t1=h+(ro(e,6)^ro(e,11)^ro(e,25))+((e&f)^(~e&gg))+k[i]+w[i],t2=(ro(a,2)^ro(a,13)^ro(a,22))+((a&bb)^(a&c)^(bb&c));h=gg;gg=f;f=e;e=d+t1;d=c;c=bb;bb=a;a=t1+t2;}s->h[0]+=a;s->h[1]+=bb;s->h[2]+=c;s->h[3]+=d;s->h[4]+=e;s->h[5]+=f;s->h[6]+=gg;s->h[7]+=h;}
static void si(Sh*s){uint32_t h[8]={0x6a09e667U,0xbb67ae85U,0x3c6ef372U,0xa54ff53aU,0x510e527fU,0x9b05688cU,0x1f83d9abU,0x5be0cd19U};memcpy(s->h,h,sizeof(h));s->bits=0;s->used=0;}static void su(Sh*s,const void*v,size_t n){const unsigned char*p=v;s->bits+=(uint64_t)n*8;while(n){size_t r=64-s->used,t=n<r?n:r;memcpy(s->b+s->used,p,t);s->used+=t;p+=t;n-=t;if(s->used==64){sb(s,s->b);s->used=0;}}}static void u64(Sh*s,uint64_t x){unsigned char b[8];for(int i=0;i<8;i++)b[7-i]=x>>(8*i);su(s,b,8);}static void sd(Sh*s,char out[65]){uint64_t bits=s->bits;unsigned char x=0x80,z=0,l[8],d[32];su(s,&x,1);while(s->used!=56)su(s,&z,1);for(int i=0;i<8;i++)l[7-i]=bits>>(8*i);su(s,l,8);for(int i=0;i<8;i++){d[4*i]=s->h[i]>>24;d[4*i+1]=s->h[i]>>16;d[4*i+2]=s->h[i]>>8;d[4*i+3]=s->h[i];}static const char h[]="0123456789abcdef";for(int i=0;i<32;i++){out[2*i]=h[d[i]>>4];out[2*i+1]=h[d[i]&15];}out[64]=0;}
static double sum(const double*x,size_t n){double s=0,c=0;for(size_t i=0;i<n;i++){double y=x[i]-c,t=s+y;c=(t-s)-y;s=t;}return s;}
int a210_publication_init(ElectronTemperaturePublication*p,size_t n){if(!p||!n)return-1;memset(p,0,sizeof(*p));p->n_shells=n;p->T_e=calloc(n,sizeof(double));p->n_e=calloc(n,sizeof(double));p->shell_status=calloc(n,sizeof(*p->shell_status));p->residual_status=calloc(n,sizeof(*p->residual_status));p->ledger=calloc(n,sizeof(*p->ledger));if(!p->T_e||!p->n_e||!p->shell_status||!p->residual_status||!p->ledger){a210_publication_free(p);return-1;}return 0;}
void a210_publication_free(ElectronTemperaturePublication*p){if(!p)return;free(p->T_e);free(p->n_e);free(p->shell_status);free(p->residual_status);free(p->ledger);memset(p,0,sizeof(*p));}
RadeqStatus a210_line_owner_finalize(A210TermLedger*l){if(!l)return RADEQ_TERM_SCHEMA;l->line_owner_overlap=l->radiative_line_included&&l->collisional_or_escape_included;if(l->m_line!=0&&l->m_line!=1){g.blocked_schema++;return l->status=RADEQ_TERM_SCHEMA;}if(l->line_owner_overlap){g.line_owner_overlap_shells++;g.blocked_schema++;return l->status=RADEQ_TERM_SCHEMA;}if((l->m_line==1)!=!!l->radiative_line_included||(l->m_line==0)!=!!l->collisional_or_escape_included){g.blocked_schema++;return l->status=RADEQ_TERM_SCHEMA;}if(l->m_line){l->cooling_status[A210_COLL_LINE]=A210_REPLACED_NOT_APPLICABLE;}else{l->heating_status[A210_LINE_ABS]=A210_REPLACED_NOT_APPLICABLE;l->cooling_status[A210_LINE_EMIT]=A210_REPLACED_NOT_APPLICABLE;}
 l->sum_heating=sum(l->heating,A210_NHEAT);l->sum_cooling=sum(l->cooling,A210_NCOOL);l->residual=l->sum_heating-l->sum_cooling;double hn=l->heating[A210_LINE_ABS],cn=l->cooling[A210_LINE_EMIT]+l->cooling[A210_COLL_LINE];double non=(l->sum_heating-hn)-(l->sum_cooling-cn);double own=l->m_line*(l->A_line-l->E_line)-(1-l->m_line)*l->C_line_ce;l->line_owner_closure=l->residual-(non+own);double scale=0;for(int i=0;i<A210_NHEAT;i++)scale+=fabs(l->heating[i]);for(int i=0;i<A210_NCOOL;i++)scale+=fabs(l->cooling[i]);scale+=fabs(own);l->normalized_line_owner_closure=scale?fabs(l->line_owner_closure)/scale:fabs(l->line_owner_closure);if((scale==0&&l->line_owner_closure!=0)||l->normalized_line_owner_closure>1e-12){g.line_owner_closure_failures++;g.blocked_schema++;if(l->normalized_line_owner_closure>g.max_line_owner_closure)g.max_line_owner_closure=l->normalized_line_owner_closure;return l->status=RADEQ_TERM_SCHEMA;}double den=l->sum_heating+l->sum_cooling;l->e_balance=den?fabs(l->residual)/den:(l->residual==0?0:INFINITY);l->status=(den==0)?RADEQ_EXACT_ZERO_BALANCE:RADEQ_OK;return l->status;}
RadeqStatus a210_te_context_sha256(const char te[65],const char geo[65],uint64_t ep,char out[65]){if(!te||!geo||!out||strlen(te)!=64||strlen(geo)!=64)return RADEQ_TE_CONTEXT_MISMATCH;Sh s;si(&s);const char d[]="A2-10:Te-context:v1";su(&s,d,sizeof(d)-1);su(&s,te,64);su(&s,geo,64);u64(&s,ep);sd(&s,out);return RADEQ_OK;}
RadeqStatus a210_geometry_sha256(const double*x,size_t n,char out[65]){if(!x||n<2||!out)return RADEQ_TE_CONTEXT_MISMATCH;Sh s;si(&s);const char d[]="A2-10:shell-geometry:cm-s^-1:IEEE754:v1";su(&s,d,sizeof(d)-1);u64(&s,n);for(size_t i=0;i<n;i++){if(!isfinite(x[i]))return RADEQ_TE_CONTEXT_MISMATCH;uint64_t v;memcpy(&v,&x[i],8);u64(&s,v);}sd(&s,out);return RADEQ_OK;}
int a210_solve_transaction(ElectronTemperaturePublication*pub,const double*lo,const double*hi,const double*ne,size_t n,uint64_t ep,uint64_t gen,const char*geo,A210ResidualFunction fn,void*ctx,double*outte,double*outne){if(!pub||!lo||!hi||!ne||!geo||!fn||!outte||!outne||!n||!gen)return 2;ElectronTemperaturePublication c={0};if(a210_publication_init(&c,n))return 2;c.solve_epoch=ep;c.required_te_generation=gen;memcpy(c.geometry_sha256,geo,65);g.solve_epoch=ep;g.te_generation_required=gen;g.shells_attempted+=n;
 for(size_t s=0;s<n;s++){if(!(isfinite(lo[s])&&isfinite(hi[s])&&lo[s]>0&&hi[s]>lo[s]&&isfinite(ne[s])&&ne[s]>=0)){g.nonfinite_failures++;a210_publication_free(&c);return 5;}A210TermLedger a={0},b={0};RadeqStatus sa=fn(s,lo[s],&a,ctx),sbv=fn(s,hi[s],&b,ctx);g.trials+=2;if((sa!=RADEQ_OK&&sa!=RADEQ_EXACT_ZERO_BALANCE)||(sbv!=RADEQ_OK&&sbv!=RADEQ_EXACT_ZERO_BALANCE)){g.blocked_schema++;a210_publication_free(&c);return 5;}double fa=a.residual,fb=b.residual;if(fa==0){c.T_e[s]=lo[s];c.ledger[s]=a;}else if(fb==0){c.T_e[s]=hi[s];c.ledger[s]=b;}else if(signbit(fa)==signbit(fb)){g.no_bracket++;a210_publication_free(&c);return 4;}else{double l=lo[s],h=hi[s];A210TermLedger m={0};for(int it=0;it<160;it++){double t=0.5*(l+h);RadeqStatus sm=fn(s,t,&m,ctx);g.trials++;if(sm!=RADEQ_OK&&sm!=RADEQ_EXACT_ZERO_BALANCE){g.nonconverged++;a210_publication_free(&c);return 5;}if(fabs(m.residual)<=1e-12*fmax(m.sum_heating+m.sum_cooling,DBL_MIN)||fabs(h-l)<=1e-12*t){c.T_e[s]=t;c.ledger[s]=m;break;}if(signbit(m.residual)==signbit(fa)){l=t;fa=m.residual;}else h=t;}if(c.T_e[s]==0){g.nonconverged++;a210_publication_free(&c);return 4;}}c.n_e[s]=ne[s];c.shell_status[s]=RADEQ_OK;c.residual_status[s]=c.ledger[s].e_balance<=1e-3?RADEQ_OK:RADEQ_HEAT_RESIDUAL;if(c.residual_status[s]!=RADEQ_OK){g.max_heat_residual=fmax(g.max_heat_residual,c.ledger[s].e_balance);a210_publication_free(&c);return 4;}if(c.ledger[s].m_line){g.line_radiative_owner_shells++;g.line_replaced_collisional_terms++;}else{g.line_collisional_escape_owner_shells++;g.line_replaced_radiative_terms+=2;}g.shells_converged++;}
 if(population_te_manifest_sha256(c.T_e,n,c.te_manifest_sha256)!=POP_OK){g.te_manifest_mismatch++;a210_publication_free(&c);return 5;}if(a210_te_context_sha256(c.te_manifest_sha256,geo,ep,c.te_context_sha256)!=RADEQ_OK){g.te_context_mismatch++;a210_publication_free(&c);return 5;}Sh sh;si(&sh);const char d[]="A2-10:term-ledger:v1";su(&sh,d,sizeof(d)-1);u64(&sh,ep);for(size_t s=0;s<n;s++)su(&sh,&c.ledger[s],sizeof(c.ledger[s]));sd(&sh,c.term_manifest_sha256);c.committed_te_generation=gen;memcpy(outte,c.T_e,n*sizeof(double));memcpy(outne,c.n_e,n*sizeof(double));ElectronTemperaturePublication old=*pub;*pub=c;memset(&c,0,sizeof(c));a210_publication_free(&old);g.te_generation_committed=gen;g.shells_published+=n;return 0;}
A210Counters*a210_counters(void){return &g;}void a210_counters_reset(void){memset(&g,0,sizeof(g));}
const char*a210_status_name(RadeqStatus s){static const char*n[]={"INVALID","RADEQ_OK","RADEQ_EXACT_ZERO_BALANCE","RADEQ_STALE_RF","RADEQ_STALE_BF","RADEQ_STALE_LINE","RADEQ_STALE_POP","RADEQ_STALE_OPACITY","RADEQ_STALE_EMISSIVITY","RADEQ_TERM_MISSING","RADEQ_TERM_SCHEMA","RADEQ_SIGN_MISMATCH","RADEQ_INVALID_TE_TRIAL","RADEQ_INVALID_NE","RADEQ_ATOMIC_MISSING","RADEQ_NO_BRACKET","RADEQ_NO_ROOT","RADEQ_NOT_CONVERGED","RADEQ_POPULATION_NOT_CONVERGED","RADEQ_CHARGE_NOT_CONVERGED","RADEQ_HEAT_RESIDUAL","RADEQ_TE_MANIFEST_MISMATCH","RADEQ_TE_CONTEXT_MISMATCH","RADEQ_UNQUALIFIED_TE","RADEQ_FIXED_T","RADEQ_FORBIDDEN_FALLBACK","RADEQ_PARTIAL_PUBLISH","RADEQ_NONFINITE"};return s>=RADEQ_OK&&s<=RADEQ_NONFINITE?n[s]:n[0];}
void a210_counters_print(FILE*f){if(!f)f=stdout;fprintf(f,"[A2-10][RADEQ] solve_epoch=%llu te_generation_required=%llu te_generation_committed=%llu shells_attempted=%llu shells_converged=%llu shells_published=%llu trials=%llu population_trials=%llu opacity_trials=%llu emissivity_trials=%llu photo_heat_terms=%llu line_heat_terms=%llu ff_heat_terms=%llu compton_heat_terms=%llu gamma_heat_terms=%llu nonthermal_heat_terms=%llu recomb_cool_terms=%llu line_cool_terms=%llu collisional_cool_terms=%llu ff_cool_terms=%llu compton_cool_terms=%llu adiabatic_cool_terms=%llu exact_zero_balance=%llu no_bracket=%llu no_root=%llu nonconverged=%llu charge_nonconverged=%llu blocked_stale=%llu blocked_missing_term=%llu blocked_schema=%llu blocked_sign=%llu te_manifest_mismatch=%llu te_context_mismatch=%llu fixed_te_attempts=%llu seed_generation_attempts=%llu line_radiative_owner_shells=%llu line_collisional_escape_owner_shells=%llu line_replaced_collisional_terms=%llu line_replaced_radiative_terms=%llu line_owner_overlap_shells=%llu line_owner_closure_failures=%llu pin_attempts=%llu floor_attempts=%llu neighbor_attempts=%llu old_te_attempts=%llu fallback_attempts=%llu partial_publish_attempts=%llu nonfinite_failures=%llu max_line_owner_closure=%.17g max_heat_residual=%.17g\n",(unsigned long long)g.solve_epoch,(unsigned long long)g.te_generation_required,(unsigned long long)g.te_generation_committed,(unsigned long long)g.shells_attempted,(unsigned long long)g.shells_converged,(unsigned long long)g.shells_published,(unsigned long long)g.trials,(unsigned long long)g.population_trials,(unsigned long long)g.opacity_trials,(unsigned long long)g.emissivity_trials,(unsigned long long)g.photo_heat_terms,(unsigned long long)g.line_heat_terms,(unsigned long long)g.ff_heat_terms,(unsigned long long)g.compton_heat_terms,(unsigned long long)g.gamma_heat_terms,(unsigned long long)g.nonthermal_heat_terms,(unsigned long long)g.recomb_cool_terms,(unsigned long long)g.line_cool_terms,(unsigned long long)g.collisional_cool_terms,(unsigned long long)g.ff_cool_terms,(unsigned long long)g.compton_cool_terms,(unsigned long long)g.adiabatic_cool_terms,(unsigned long long)g.exact_zero_balance,(unsigned long long)g.no_bracket,(unsigned long long)g.no_root,(unsigned long long)g.nonconverged,(unsigned long long)g.charge_nonconverged,(unsigned long long)g.blocked_stale,(unsigned long long)g.blocked_missing_term,(unsigned long long)g.blocked_schema,(unsigned long long)g.blocked_sign,(unsigned long long)g.te_manifest_mismatch,(unsigned long long)g.te_context_mismatch,(unsigned long long)g.fixed_te_attempts,(unsigned long long)g.seed_generation_attempts,(unsigned long long)g.line_radiative_owner_shells,(unsigned long long)g.line_collisional_escape_owner_shells,(unsigned long long)g.line_replaced_collisional_terms,(unsigned long long)g.line_replaced_radiative_terms,(unsigned long long)g.line_owner_overlap_shells,(unsigned long long)g.line_owner_closure_failures,(unsigned long long)g.pin_attempts,(unsigned long long)g.floor_attempts,(unsigned long long)g.neighbor_attempts,(unsigned long long)g.old_te_attempts,(unsigned long long)g.fallback_attempts,(unsigned long long)g.partial_publish_attempts,(unsigned long long)g.nonfinite_failures,g.max_line_owner_closure,g.max_heat_residual);}
